D={
82088:("If I were you","Conselho com **If I were you, I'd + verbo**. Soa educado e suave.",[("{{If I were you}}, I'd ask for help.","Se eu fosse você, pediria ajuda."),("{{I'd be}} honest with her.","Eu seria honesto com ela."),("{{I wouldn't}} do that.","Eu não faria isso."),("{{Why don't you}} wait?","Por que você não espera?")],"Qual está certa?",["If I was you, I'd go.","If I were you, I'd go.","If I am you, I'd go."],1,"If I were you."),
930019:("actually / in fact","**Actually** corrige; **in fact** reforça; **indeed** confirma; *actually* NÃO é “atualmente”.",[("{{Actually}}, I love it.","Na verdade, eu adoro."),("{{In fact}}, I made time.","De fato, arranjei tempo."),("{{Indeed}}, it was a good idea.","De fato, foi uma boa ideia."),("{{As a matter of fact}}, I know her.","Na verdade, eu a conheço.")],"“Actually” em inglês significa…",["atualmente","na verdade","imediatamente"],1,"Falso cognato."),
82089:("unless / otherwise","**Unless** = if not; **otherwise / or else** = caso contrário. Depois de unless: presente.",[("We'll go {{unless}} it rains.","Iremos a menos que chova."),("Hurry, {{otherwise}} we'll be late.","Ande, caso contrário chegaremos tarde."),("Pay now, {{or else}} I'll leave.","Pague agora, senão eu vou embora."),("{{Unless}} you hurry, you'll miss it.","A menos que se apresse, vai perder.")],"Qual é o mesmo que “if not”?",["otherwise","unless","although"],1,"Unless."),
81140:("unless","**Unless** = a menos que.",[("We will ski {{unless}} it's too cold.","Esquiaremos a menos que esteja frio demais."),("{{Put on}} your boots.","Calce suas botas."),("The slope is very {{steep}}.","A pista é muito íngreme."),("We'll stay in {{unless}} it snows.","Ficaremos em casa a menos que nevem.")],"“Unless it rains” equivale a…",["if it rains","if it doesn't rain","because it rains"],1,"If not."),
82090:("as long as / provided that","**As long as** e **provided that** = desde que; com o **presente**.",[("You can stay {{as long as}} you behave.","Pode ficar desde que se comporte."),("I'll go {{provided that}} you pay.","Eu vou, contanto que você pague."),("I agree {{as long as}} it's fair.","Concordo desde que seja justo."),("{{Provided}} it's safe, we'll go.","Desde que seja seguro, iremos.")],"“As long as” expressa…",["condição","tempo","lugar"],0,"Condição firme."),
82091:("What if?","**What if + passado + would**. Também *suppose / imagine + passado*.",[("{{What if}} I won a million?","E se eu ganhasse um milhão?"),("{{Suppose}} you could fly?","Suponha que você pudesse voar."),("{{Imagine}} you lived on Mars.","Imagine que você morasse em Marte."),("What would you do {{if}} it happened?","O que você faria se acontecesse?")],"Qual é uma pergunta hipotética?",["What if we lived on Mars?","What we live Mars?","What if live?"],0,"What if + passado."),
82092:("zero × first","**Zero**: verdade sempre. **First**: possibilidade futura (*will*).",[("If you mix red and blue, you {{get}} purple.","Se mistura vermelho e azul, obtém roxo."),("If I find a clue, I'{{ll tell}} you.","Se eu achar uma pista, aviso você."),("If it rains hard, the river {{floods}}.","Se chove forte, o rio transborda."),("If it floods, we'{{ll move}}.","Se transbordar, nos mudaremos.")],"Qual é fato sempre verdadeiro?",["If it rains, I'll stay.","If you heat ice, it melts.","If it rained, I'd stay."],1,"Zero conditional."),
930020:("collocations com have","**Have a look, a chat, a go, a laugh, a rest, a word**.",[("{{Have a look}} at this.","Dê uma olhada nisto."),("I'll {{have a go}} at it.","Vou tentar."),("I need to {{have a rest}}.","Preciso descansar."),("Let's {{have a chat}}.","Vamos bater um papo.")],"“Have a go” significa…",["tentar","ir embora","gritar"],0,"Experimentar."),
82093:("Second conditional","Outra vida: **if + passado, would + verbo**; **were** para todos.",[("If I {{lived}} by the sea, I'd surf every day.","Se eu morasse perto do mar, surfaria todo dia."),("If I {{were}} braver, I'd jump.","Se eu fosse mais corajoso, pularia."),("If I {{changed}} my mind, I'd call you.","Se eu mudasse de ideia, ligaria."),("I {{would}} travel more.","Eu viajaria mais.")],"Qual está certa?",["If I would live, I'd go.","If I lived, I'd go.","If I live, I'd go."],1,"If + passado."),
82094:("would: o que faria","**If I had…, I'd…** para o que você faria.",[("If I {{had}} a million, I'd buy a house.","Se eu tivesse um milhão, compraria uma casa."),("I'd {{give}} half to charity.","Eu daria metade para caridade."),("I {{wouldn't quit}} my job.","Eu não largaria meu emprego."),("I'd spend half and {{save}} half.","Gastaria metade e guardaria metade.")],"“I wouldn't” significa…",["I would not","I will not","I was not"],0,"Wouldn't = would not."),
82095:("Pedidos polidos","**Could you…? Would you mind + -ing? I'd be grateful if you could…**",[("{{Could you}} tell me the time?","Poderia me dizer as horas?"),("{{Would you mind opening}} the window?","Você se importaria de abrir a janela?"),("{{I'd be grateful if you could}} help.","Ficaria grato se pudesse ajudar."),("{{I'd appreciate it if}} you waited.","Eu agradeceria se você esperasse.")],"Qual é mais polido?",["Open it.","Would you mind opening it?","You open it."],1,"Would you mind…?"),
82096:("so that / as a result","**So that** = para que; **as a result** = como resultado; **if + presente, will** = consequência.",[("Plant trees {{so that}} they can grow.","Plante árvores para que elas cresçam."),("He cut the trees. {{As a result}}, animals left.","Ele cortou as árvores. Como resultado, os animais partiram."),("If we cut more, the forest {{will die}}.","Se cortarmos mais, a floresta morrerá."),("{{Therefore}}, we must stop.","Portanto, devemos parar.")],"“As a result” indica…",["causa","consequência","condição"],1,"Resultado."),
930021:("empatia","**I'm sorry to hear that. That must be hard. If there's anything I can do…**",[("{{I'm sorry to hear that}}.","Sinto muito saber disso."),("{{That must be hard}} for you.","Deve ser difícil para você."),("{{My thoughts are with}} your family.","Meus pensamentos estão com sua família."),("{{If there's anything I can do}}, tell me.","Se eu puder fazer algo, diga.")],"Como consolar?",["I'm sorry to hear that.","Congratulations!","See you."],0,"Solidariedade."),
82097:("maybe / perhaps / might","**Maybe / perhaps** no começo; **might / may / could** antes do verbo; **might have + particípio** para o passado.",[("{{Maybe}} he is lying.","Talvez ele esteja mentindo."),("He {{might be}} lying.","Ele pode estar mentindo."),("She {{might have forgotten}}.","Ela pode ter esquecido."),("{{Perhaps}} it's true.","Talvez seja verdade.")],"Qual está certa?",["Might he lying.","He might be lying.","He might lying."],1,"Might + be + -ing."),
82098:("Negociar","**If you…, I'll…** (oferta real); **If you could…, I'd…** (mais educado); **Let's meet halfway**.",[("If you buy two, {{I'll give}} a discount.","Se você comprar dois, dou desconto."),("If you {{could}} go lower, I'd sign.","Se você pudesse baixar, eu assinaria."),("{{Let's meet halfway}}.","Vamos chegar a um meio-termo."),("{{Would you consider}} a lower price?","Você consideraria um preço menor?")],"“Meet halfway” significa…",["chegar a um acordo","ir embora","adiar"],0,"Meio-termo."),
82099:("Avisar","**If you…, you might/will…** *Might* = risco; *will* = certeza.",[("If you touch it, you {{might get}} hurt.","Se tocar nisso, pode se machucar."),("If you run, it {{will chase}} you.","Se correr, ele vai perseguir você."),("If the fence breaks, animals {{will escape}}.","Se a cerca quebrar, os animais fugirão."),("{{Be careful}}, otherwise you'll fall.","Tenha cuidado, senão vai cair.")],"Qual indica certeza?",["might","will","may"],1,"Will."),
82100:("Revisão: condicionais","**Zero** (fatos), **first** (real), **second** (irreal), **third** (passado).",[("If I'm late, I {{call}} you.","Se me atraso, ligo para você."),("If I'm late tomorrow, I'{{ll call}} you.","Se me atrasar amanhã, ligarei."),("If I {{were}} rich, I {{would travel}}.","Se eu fosse rico, viajaria."),("If I {{had left}}, I {{would have missed}} it.","Se eu tivesse saído, teria perdido.")],"Qual é o terceiro condicional?",["If I knew, I'd tell.","If I had known, I'd have told.","If I know, I'll tell."],1,"If + had + particípio."),
82101:("must be / can't be","**Must be** = certeza; **can't be** = impossível; **might** = possível.",[("He {{must be}} a soldier.","Ele deve ser soldado."),("He {{can't be}} a farmer.","Ele não pode ser fazendeiro."),("She {{must have left}} already.","Ela deve ter ido já."),("It {{might be}} a clue.","Pode ser uma pista.")],"“He can't be a doctor” significa…",["Ele talvez seja.","É impossível que seja.","Ele é."],1,"Certeza negativa."),
930022:("hold on / hold back","**Hold on** = esperar; **hold back** = conter; **hold up** = atrasar/aguentar; **hold out** = resistir.",[("{{Hold on}} a second.","Espere um segundo."),("I {{hold back}} my fear.","Contenho meu medo."),("It {{holds up}} until help comes.","Aguenta até chegar ajuda."),("We can {{hold out}} a few days.","Podemos resistir alguns dias.")],"“Hold on” significa…",["esperar","largar","correr"],0,"Esperar."),
82102:("might have / could have","**Might / could have + particípio** = possibilidade no passado; **can't have** = impossível.",[("He {{might have taken}} it.","Ele pode ter pegado."),("It {{could have been}} a mistake.","Pode ter sido um engano."),("She {{can't have done}} it.","Ela não pode ter feito isso."),("He {{might not have known}}.","Ele pode não ter sabido.")],"“She can't have done it” significa…",["Talvez ela tenha feito.","É impossível que tenha feito.","Ela fez."],1,"Can't have."),
82103:("should have","**Should have + particípio** = devia ter; **shouldn't have** = não devia ter; **ought to have**.",[("I {{should have called}} her.","Eu devia ter ligado para ela."),("I {{shouldn't have told}} him.","Eu não devia ter contado a ele."),("You {{ought to have known}} better.","Você devia ter percebido."),("We {{should have left}} earlier.","Devíamos ter saído mais cedo.")],"“I should have called” = …",["Liguei.","Não liguei, mas devia.","Vou ligar."],1,"Crítica ao passado."),
82104:("could × was able to","**Could** = capacidade geral; **was able to / managed to** = conquista específica.",[("I {{could swim}} at five.","Eu sabia nadar aos cinco."),("I {{managed to pass}} the exam.","Consegui passar na prova."),("She {{was able to}} feel the water.","Ela conseguiu sentir a água."),("I {{couldn't}} find it.","Não consegui achar.")],"Qual conquista específica?",["I could swim.","I managed to finish.","I could ride."],1,"Managed to."),
82105:("have to / must / allowed to","**Have to** = regra externa; **must** = pessoal; **be allowed to** = permissão.",[("I {{have to}} wear a uniform.","Preciso usar uniforme."),("We're {{allowed to}} leave early.","Temos permissão para sair cedo."),("You {{mustn't}} talk here.","Você não pode falar aqui."),("I'm {{not allowed to}} park.","Não posso estacionar.")],"“Not allowed to” significa…",["proibido","obrigado","capaz"],0,"Proibido."),
82106:("needn't × mustn't","**Don't have to / needn't** = não precisa; **mustn't** = proibido.",[("You {{don't have to}} hurry.","Você não precisa se apressar."),("You {{needn't}} worry.","Não precisa se preocupar."),("It {{isn't necessary}}.","Não é necessário."),("You {{mustn't}} touch it.","Você não pode tocar.")],"“You don't have to come” =",["Você não pode vir.","Não é obrigatório vir.","Você deve vir."],1,"Não é necessário."),
930023:("idioms de eficiência","**Kill two birds with one stone** = duas coisas de uma vez; **get the ball rolling** = começar; **on the right track** = no caminho certo.",[("I'll {{kill two birds with one stone}}.","Resolvo duas coisas de uma vez."),("Let's {{get the ball rolling}}.","Vamos começar."),("You're {{on the right track}}.","Você está no caminho certo."),("That {{saves}} time.","Isso economiza tempo.")],"“Get the ball rolling” significa…",["começar","parar","jogar bola"],0,"Dar início."),
82107:("Pedir permissão","**Can** (informal) < **could** < **may** (formal) < **would you mind…?**",[("{{May I}} make a suggestion?","Posso fazer uma sugestão?"),("{{Could I}} borrow your pen?","Posso pegar sua caneta emprestada?"),("{{Would you mind if I}} opened the window?","Você se importaria se eu abrisse a janela?"),("{{Go ahead}}.","Fique à vontade.")],"Qual resposta aceita?",["Go ahead.","I'm afraid not.","No way."],0,"Go ahead."),
82108:("Pedidos","**Can you** (informal) < **could you** < **would you** < **would you mind**.",[("{{Could you}} pass the salt?","Poderia passar o sal?"),("{{Would you mind closing}} the door?","Você se importaria de fechar a porta?"),("{{Can you}} help me, please?","Pode me ajudar, por favor?"),("{{Will you}} be quiet?","Quer fazer silêncio?")],"Qual é o mais polido?",["Can you?","Would you mind?","Will you?"],1,"Would you mind."),
82109:("Shall / Why don't / How about","**Shall we/I…?** **Why don't we…?** **How about + -ing?**",[("{{Shall we}} go to the park?","Vamos ao parque?"),("{{Shall I}} make some breakfast?","Quer que eu faça o café da manhã?"),("{{How about driving}} instead?","Que tal dirigirmos?"),("{{Why don't we}} walk?","Por que não caminhamos?")],"“Shall I…?” oferece…",["ajuda","comida","tempo"],0,"Oferta."),
82110:("had better / ought to","**Had better** = é melhor (com ameaça); **ought to** = devia.",[("You'd {{better}} stop now.","É melhor você parar agora."),("You {{ought to}} see a doctor.","Você devia ver um médico."),("You'd better {{not}} wait.","É melhor não esperar."),("It {{is}} a warning.","É um aviso.")],"Qual é mais forte?",["should","had better","could"],1,"Had better."),
82111:("Proibições","**Mustn't**, **can't**, **not allowed to**, **forbidden / prohibited**.",[("Reading is {{forbidden}} here.","Ler é proibido aqui."),("Phones {{aren't permitted}} in class.","Celulares não são permitidos na aula."),("You {{mustn't}} burn books.","Você não pode queimar livros."),("It's {{illegal}} to park here.","É ilegal estacionar aqui.")],"Qual é uma proibição oficial?",["It's forbidden.","It's optional.","It's allowed."],0,"Forbidden."),
930024:("keep up with / keep on","**Keep up with** = acompanhar; **keep on** = continuar; **keep out** = ficar fora; **keep away from** = ficar longe.",[("I {{keep up with}} technology.","Acompanho a tecnologia."),("I'll {{keep on}} trying.","Vou continuar tentando."),("Please {{keep out}} of danger.","Fique longe do perigo."),("{{Keep away from}} the edge.","Fique longe da beirada.")],"“Keep on” significa…",["continuar","manter fora","acompanhar"],0,"Continuar."),
82112:("will / would: hábitos","**Will** = hábito/traço do presente; **would** = hábito do passado.",[("She'll often {{hum}} a song.","Ela costuma cantarolar."),("She {{would buy}} flowers every morning.","Ela comprava flores toda manhã."),("He {{will}} sit for hours.","Ele fica sentado por horas."),("As a girl, she {{would}} sing.","Quando menina, ela cantava.")],"Qual NÃO aceita would?",["Habit","State (I used to be shy)","Repeated action"],1,"Estado: used to."),
82113:("Graus de certeza","**Definitely > probably > possibly > unlikely > definitely not**.",[("He will {{definitely}} win.","Ele certamente vencerá."),("It will {{probably}} rain tomorrow.","Provavelmente vai chover amanhã."),("She may {{possibly}} come.","Ela possivelmente virá."),("He {{definitely won't}} win.","Ele certamente não vencerá.")],"Qual é o mais certo?",["possibly","probably","definitely"],2,"Definitely."),
82114:("could × would","**Could**: capacidade passada, possibilidade, pedido. **Would**: hipótese, hábito, oferta.",[("I {{could}} swim at five.","Eu sabia nadar aos cinco."),("I {{would}} go if I had time.","Eu iria se tivesse tempo."),("{{Would you like}} to join us?","Gostaria de se juntar a nós?"),("It {{could}} rain.","Pode chover.")],"Qual é uma oferta?",["Could you help?","Would you like tea?","I could swim."],1,"Would you like?"),
82115:("be able to","**Be able to** = ter capacidade; serve onde *can* não funciona.",[("I'm {{able to}} run five miles.","Sou capaz de correr oito quilômetros."),("I {{was able to}} finish.","Consegui terminar."),("I'll {{be able to}} come tomorrow.","Poderei vir amanhã."),("I {{haven't been able to}} sleep.","Não tenho conseguido dormir.")],"Qual está certa?",["I'll can come.","I'll be able to come.","I'll be able come."],1,"Will be able to."),
82116:("need to / have got to","**Need to** = precisar; **have got to** = informal forte; **must** = muito forte.",[("I {{need to}} save money.","Preciso economizar."),("I've {{got to}} go now.","Tenho que ir agora."),("I {{must}} tell you something.","Preciso te contar algo."),("You {{don't need to}} wait.","Você não precisa esperar.")],"“I've got to go” é…",["formal","informal e forte","opcional"],1,"Informal."),
930025:("Personalidade","**Stubborn, generous, reliable, ambitious, moody** + *seems*.",[("He is {{stubborn}} and proud.","Ele é teimoso e orgulhoso."),("He {{seems}} moody today.","Ele parece mal-humorado hoje."),("She is {{reliable}}.","Ela é confiável."),("Don't {{judge}} people by their looks.","Não julgue as pessoas pela aparência.")],"“Reliable” significa…",["confiável","teimoso","ambicioso"],0,"Reliable = confiável."),
82117:("should / ought to: probabilidade","**Should / ought to** = provável; **must** = quase certo; **should have** = já devia.",[("He {{should}} be here soon.","Ele deve chegar logo."),("He {{should have arrived}} by now.","Ele já devia ter chegado."),("It {{ought to}} be easy.","Deve ser fácil."),("He {{must}} be tired.","Ele deve estar cansado.")],"“He should be here soon” expressa…",["expectativa","obrigação","proibição"],0,"Expectativa."),
82118:("should have / could have","**Should have** = devia ter; **could have** = poderia ter (e não fez).",[("You {{should have asked}} first.","Você devia ter perguntado antes."),("She {{could have taken}} a taxi.","Ela poderia ter pegado um táxi."),("He {{shouldn't have lied}}.","Ele não devia ter mentido."),("We {{could have stayed}}.","Poderíamos ter ficado.")],"“Could have taken” = …",["Pegou.","Poderia ter pegado (não pegou).","Vai pegar."],1,"Possibilidade não realizada."),
82119:("Revisão dos modais","Certeza: *must be, can't be*. Possibilidade: *might, may, could*. Obrigação: *must, have to*. Proibição: *mustn't*. Não necessidade: *needn't*.",[("You {{must be}} joking.","Você deve estar brincando."),("This {{might be}} serious.","Isto pode ser sério."),("You {{mustn't}} break the rules.","Você não pode quebrar as regras."),("You {{needn't}} worry.","Não precisa se preocupar.")],"Qual expressa certeza?",["might","must be","could"],1,"Must be."),
82120:("Present passive","**Is/are + particípio**: foco no processo.",[("Cars {{are made}} in a factory.","Carros são fabricados numa fábrica."),("The machine {{is controlled}} by a worker.","A máquina é controlada por um operário."),("The parts {{are checked}} carefully.","As peças são verificadas com cuidado."),("Parts {{aren't checked}} here.","As peças não são verificadas aqui.")],"Qual está no passivo?",["They make cars.","Cars are made.","Cars make."],1,"Are made."),
82121:("Past passive","**Was/were + particípio**: *The palace was built in 1650.*",[("The palace {{was built}} in 1650.","O palácio foi construído em 1650."),("The walls {{were painted}} white.","As paredes foram pintadas de branco."),("It {{wasn't finished}} on time.","Não foi terminado no prazo."),("{{Who was}} it {{designed}} by?","Por quem foi projetado?")],"Complete: “The walls ___ painted.”",["was","were","are"],1,"Walls: were."),
930026:("collocations com give","**Give advice, a speech, an example, permission, notice**. *Advice* não leva *an*.",[("Let me {{give you an example}}.","Deixe-me dar um exemplo."),("He {{gave permission}}.","Ele deu permissão."),("She {{gave a speech}}.","Ela fez um discurso."),("I'll {{give advice}}.","Vou dar conselhos.")],"Qual está certa?",["an advice","some advice","advices"],1,"Advice é incontável."),
81271:("Past passive","**Was/were + particípio** mostra o que aconteceu com algo.",[("The plane {{was built}} in 1903.","O avião foi construído em 1903."),("The wings {{were made}} of wood.","As asas foram feitas de madeira."),("{{When was}} it {{built}}?","Quando foi construído?"),("Many things {{were invented}}.","Muitas coisas foram inventadas.")],"Qual é o particípio de “invent”?",["invented","invent","inventing"],0,"Regular: -ed."),
82122:("Perguntas no passivo","**Was/Were + sujeito + particípio?** Com wh-: *Where was it found?*",[("{{Where was}} it {{found}}?","Onde foi encontrado?"),("{{Who was}} it {{painted}} by?","Por quem foi pintado?"),("{{Were they invited}}?","Eles foram convidados?"),("Yes, it {{was}}.","Sim, foi.")],"Qual está certa?",["Where it was found?","Where was it found?","Where was found it?"],1,"Wh + was + sujeito."),
82123:("Passivo com by","**By** diz quem fez, se for relevante.",[("It was painted {{by}} Van Gogh.","Foi pintado por Van Gogh."),("It was written {{by}} a young author.","Foi escrito por um jovem autor."),("The window was broken {{by}} the wind.","A janela foi quebrada pelo vento."),("It was recommended {{by}} a friend.","Foi recomendado por um amigo.")],"Quando usar by?",["Sempre","Quando o autor é relevante","Nunca"],1,"Só quando importa."),
82124:("Passivo nas notícias","Notícias usam o passivo porque o **fato** importa mais que o autor.",[("Two men {{were arrested}}.","Dois homens foram presos."),("The case {{is being investigated}}.","O caso está sendo investigado."),("A reporter {{was sent}} to the scene.","Um repórter foi enviado ao local."),("Three people {{were injured}}.","Três pessoas ficaram feridas.")],"Qual é o foco?",["quem prendeu","quem foi preso","quando prendeu"],1,"O fato."),
81297:("Past passive","**Was/were + particípio**: *The statue was made in France.*",[("The statue {{was made}} in France.","A estátua foi feita na França."),("The bridges {{were built}} long ago.","As pontes foram construídas há muito."),("{{Where was}} it {{made}}?","Onde foi feita?"),("The tower {{was opened}} in 1889.","A torre foi inaugurada em 1889.")],"Complete: “The bridge ___ opened in 1883.”",["was","were","is"],0,"Singular: was."),
930027:("let down / let in","**Let down** = decepcionar; **let in** = deixar entrar; **let out** = soltar; **let go of** = largar.",[("I won't {{let you down}} again.","Não vou decepcionar você de novo."),("{{Let him in}} now.","Deixe-o entrar agora."),("I can't {{let go of}} your hand.","Não consigo soltar sua mão."),("They {{let out}} the dog.","Eles soltaram o cachorro.")],"“Let down” significa…",["decepcionar","deixar cair","soltar"],0,"Decepcionar."),
82125:("Future passive","**Will be + particípio**: *The winner will be announced.*",[("The winner {{will be announced}} tomorrow.","O vencedor será anunciado amanhã."),("The capsule {{will be buried}} in the park.","A cápsula será enterrada no parque."),("It {{won't be opened}} soon.","Não será aberto logo."),("{{Will it be}} cleared?","Será liberado?")],"Qual está certa?",["It will be done.","It will done.","It be done."],0,"Will be + particípio."),
82126:("Modais no passivo","**Modal + be + particípio**; passado: **modal + have been + particípio**.",[("It {{can be repaired}}.","Pode ser consertado."),("It {{must be locked}} at night.","Deve ser trancado à noite."),("It {{can't be controlled}}.","Não pode ser controlado."),("It {{should have been done}}.","Devia ter sido feito.")],"Qual está certa?",["It can fixed.","It can be fixed.","It can be fix."],1,"Can be + particípio."),
82127:("have something done","**Have/get + algo + particípio**: alguém faz o serviço para você.",[("I {{had my suit repaired}} last week.","Mandei consertar meu terno semana passada."),("She {{has her nails done}} every month.","Ela faz as unhas todo mês."),("He {{got his hair cut}} on Saturday.","Ele cortou o cabelo no sábado."),("I'm {{having}} my car washed.","Estou mandando lavar o carro.")],"“I had my hair cut” = …",["Cortei sozinho.","Alguém cortou para mim.","Vou cortar."],1,"Serviço feito por outro."),
81341:("get something done","**Get + algo + particípio** = serviço feito por outra pessoa.",[("I {{get my eyes checked}}.","Faço exame de vista."),("I'm going to {{get new glasses}}.","Vou comprar óculos novos."),("She {{gets her hair cut}}.","Ela corta o cabelo no salão."),("It looks {{blurry}}.","Está embaçado.")],"Qual está certa?",["I get my eyes check.","I get my eyes checked.","I get check my eyes."],1,"Particípio."),
82128:("it is said that","**It is said/believed that…** ou **He is said to be…**: formal, comum em notícias.",[("{{It is said that}} he was brave.","Diz-se que ele era corajoso."),("{{It is believed that}} magic was real.","Acredita-se que a magia era real."),("He {{is said to be}} brave.","Diz-se que ele é corajoso."),("The castle {{is said to be}} haunted.","Dizem que o castelo é assombrado.")],"Qual está certa?",["He is said to be brave.","He says to be brave.","He said be brave."],0,"Is said to be."),
930028:("gírias de lazer","**Grab a bite, kick back, hit the town**; *bro, mate, buddy* chamam amigos.",[("Let's {{grab a bite}} after school.","Vamos comer algo depois da escola."),("Let's {{kick back}} after that.","Vamos relaxar depois."),("Let's {{hit the town}}!","Vamos curtir a noite!"),("Hey, {{bro}}!","E aí, cara!")],"“Kick back” significa…",["relaxar","chutar","voltar"],0,"Relaxar."),
}
